INSERT INTO session_situations(session_id,id,code,title,body,display_order) VALUES
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','EXHIBITION_01','길에 쓰레기가 떨어져 있다','길에 쓰레기가 떨어져 있다',1),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000002','EXHIBITION_02','빨간불인데 차가 한 대도 없다','빨간불인데 차가 한 대도 없다',2),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000003','EXHIBITION_03','누군가 지갑을 떨어뜨렸다','누군가 지갑을 떨어뜨렸다',3),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000004','EXHIBITION_04','버스 정류장에서 누군가 새치기한다','버스 정류장에서 누군가 새치기한다',4),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000005','EXHIBITION_05','길을 잃은 아이가 울고 있다','길을 잃은 아이가 울고 있다',5),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000006','EXHIBITION_06','공원에서 누군가 큰 소리로 음악을 틀고 있다','공원에서 누군가 큰 소리로 음악을 틀고 있다',6),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000007','EXHIBITION_07','불법 주차된 차 때문에 통행이 어렵다','불법 주차된 차 때문에 통행이 어렵다',7),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000008','EXHIBITION_08','카페 직원이 거스름돈을 더 줬다','카페 직원이 거스름돈을 더 줬다',8),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000009','EXHIBITION_09','지하철에서 자리가 하나 났다','지하철에서 자리가 하나 났다',9),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000010','EXHIBITION_10','친구가 시험에서 부정행위를 하자고 한다','친구가 시험에서 부정행위를 하자고 한다',10),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000011','EXHIBITION_11','분리수거장이 엉망이다','분리수거장이 엉망이다',11),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000012','EXHIBITION_12','가까운 거리에 이동해야 한다','가까운 거리에 이동해야 한다',12),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000013','EXHIBITION_13','꽃밭에 들어가면 사진이 잘 나올 것 같다','꽃밭에 들어가면 사진이 잘 나올 것 같다',13),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000014','EXHIBITION_14','동네 하천에 쓰레기가 쌓여 있다','동네 하천에 쓰레기가 쌓여 있다',14),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000015','EXHIBITION_15','일회용품과 다회용품 중 선택할 수 있다','일회용품과 다회용품 중 선택할 수 있다',15),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000016','EXHIBITION_16','이웃이 무거운 짐을 들고 있다','이웃이 무거운 짐을 들고 있다',16),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000017','EXHIBITION_17','동네 축제 자원봉사자를 모집한다','동네 축제 자원봉사자를 모집한다',17),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000018','EXHIBITION_18','길고양이에게 먹이를 주고 싶다','길고양이에게 먹이를 주고 싶다',18),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000019','EXHIBITION_19','공용 화장실 바닥에 휴지가 떨어져 있다','공용 화장실 바닥에 휴지가 떨어져 있다',19),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000020','EXHIBITION_20','주민들이 공원에 나무를 심고 있다','주민들이 공원에 나무를 심고 있다',20),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000021','EXHIBITION_21','길거리에서 두 사람이 싸우고 있다','길거리에서 두 사람이 싸우고 있다',21),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000022','EXHIBITION_22','친구가 다른 사람의 비밀을 알려줬다','친구가 다른 사람의 비밀을 알려줬다',22),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000023','EXHIBITION_23','식당에서 주문하지 않은 비싼 음식이 나왔다','식당에서 주문하지 않은 비싼 음식이 나왔다',23),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000024','EXHIBITION_24','공원 금지구역을 지나가면 지름길이다','공원 금지구역을 지나가면 지름길이다',24),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000025','EXHIBITION_25','가게에서 누군가 물건을 훔치는 걸 봤다','가게에서 누군가 물건을 훔치는 걸 봤다',25),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000026','EXHIBITION_26','갑자기 정전이 발생했다','갑자기 정전이 발생했다',26),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000027','EXHIBITION_27','폭우로 도로 일부가 침수됐다','폭우로 도로 일부가 침수됐다',27),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000028','EXHIBITION_28','행사 때문에 도로가 통제됐다','행사 때문에 도로가 통제됐다',28),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000029','EXHIBITION_29','화재경보가 울렸는데 불은 보이지 않는다','화재경보가 울렸는데 불은 보이지 않는다',29),
  ('16000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000030','EXHIBITION_30','도시 광장에서 정체불명의 상자를 발견했다','도시 광장에서 정체불명의 상자를 발견했다',30);
